<script>
import Layout from "../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";
import moment from "moment";
import { Modal } from "bootstrap";
import reportHeaderV2 from "@/components/report-header-v2.vue";
export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
    reportHeaderV2,
  },
  data() {
    return {
      currenTotal: 0,
      day: moment(new Date(Date.now())).format("YYYY-MM-DD"),
      payid: [],
      billing_invoices: [],
      customerData: [],
      page: 1,
      total: 0,
      status: 1,
      limit: 20,
      pay_amount: 0,
      total_amount: 0,
      tot_pages: 0,
      searchModel: "",
      customerInfo: [],
      search: "",
      matchedCustomers: null,
      bill: [],
      allSelected: false,
      selectedCustomer: null,
      detailed_customer: null,
      searchInput: null,
      customer_bill_id: null,
      reference_no: null,
      bill_modal: {},
      previous_receivable: 0,
      unearned: 0,
    };
  },
  computed: {
    generate() {
      return this.final_total
        .map((c) => {
          console.log("total", c.customer.tariff.fees);
          return c.customer.tariff.fees;
        })
        .reduce((a, b) => {
          this.total = parseInt(a) + parseInt(b);
          return this.total;
        }, 0);
    },
  },
  methods: {
    pay_bill() {
      const user = JSON.parse(localStorage.currentUser);
      if (!user) return;
      this.http
        .post("billing-invoices/pay-billings", {
          amount: this.pay_amount,
          customer_id: this.selectedCustomer?.id,
          user_id: user?.id,
          reference_no: this.reference_no,
        })
        .then((resp) => {
          console.log("done");
          this.pay_amount = 0;
          this.total_amount = resp.data[0].total;
          this.selectCustomer();

          this.bill_modal.hide();
        });
    },
    searchCustomer(search) {
      this.http
        .post("customers/search", {
          search,
          page: 1,
          limit: 20,
        })
        .then((res) => {
          const selectCustomerInput = document.getElementById("selectUser");
          if (selectCustomerInput) {
            selectCustomerInput.blur();
          }
          this.matchedCustomers = res.data;
        });
    },
    selectCustomer() {
      this.tot_pages = 0;
      this.http
        .post("billing-invoices/search", {
          customer_id: this.selectedCustomer.id,
          limit: this.limit,
          page: this.page,
        })
        .then((res) => {
          this.detailed_customer = res.customer;
          this.total_amount = res.total_amount;
          this.billing_invoices = res?.billing_invoices;
          this.previous_receivable = res?.previous_receivable;
          this.unearned = res?.unearned_revenue;
        });
    },
    pay() {
      console.log("@@@@2", this.day);
      this.billing_invoices?.map((a) => {
        this.payid.push({ id: a.id });
      }),
        console.log("billing", this.billing_invoices);
      this.billing_invoices?.customer?.name;
      this.http
        .post("billing-invoices/update", {
          status: this.status,
          billing_invoices: this.bill,
          code: this.billing_invoices[0]?.customer?.code,
          name: this.billing_invoices[0]?.customer?.name,
        })
        .then(() => {
          // this.get(this.page)
          this.searchCustomer(this.searchModel);
        });
    },

    get(page) {
      this.day = moment(new Date(Date.now())).format("YYYY-MM-DD");
      console.log(page);
      this.http
        .post("billing-invoices/pagination", {
          limit: this.limit,
          page: page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
        });
    },
    showLabel(customerInfo) {
      return (
        customerInfo.id +
        "-" +
        "(" +
        customerInfo.meter_no +
        ")" +
        "-" +
        customerInfo.name
      );
    },
  },

  created() {},
  mounted() {
    this.bill_modal = new Modal("#bill");
  },
};
</script>

